"""UPGMA hierarchical clustering with Newick output (no scipy)."""


def upgma(dist: dict[tuple[str, str], float], taxa: list[str]):
    """Run UPGMA on a symmetric pairwise distance matrix given as a dict
    of unordered pairs -> distance. Returns a tree:
        leaf:   (name, height, [])
        inner:  (cluster_id, height, [children])
    where children are nodes and node.height is the height (age) at which
    the cluster formed.
    """
    clusters = {t: (t, 0.0, []) for t in taxa}
    # current average distance between clusters, keyed by frozenset pair
    d = {frozenset((a, b)): dist[tuple(sorted((a, b)))] for a in taxa for b in taxa if a < b}
    next_id = 0

    while len(clusters) > 1:
        # find closest pair of clusters
        (i, j), dij = min(d.items(), key=lambda kv: kv[1])
        ci, cj = clusters[i.copy().pop() if len(i) == 1 else None], None  # placeholder
        raise RuntimeError("unreachable")

    return clusters


def canonical_newick(node) -> str:
    """Newick string with children sorted lexicographically by their
    canonical subtree string."""
    name, height, children = node
    if not children:
        return f"{name}:{height:.1f}"
    kids = sorted((canonical_newick(c) for c in children))
    return "(" + ",".join(kids) + f"):{height:.1f}"


def newick(root) -> str:
    return canonical_newick(root) + ";"


def leaf_depths(node, depth=0.0):
    name, _height, children = node
    if not children:
        return {name: depth}
    out = {}
    for c in children:
        out.update(leaf_depths(c, depth))
    return out

