"""UPGMA hierarchical clustering with Newick output (pure Python, no scipy).

Tree node representation:
    {"name": str|None, "height": float, "children": [node, ...], "length": float}
`height` is the age at which the cluster formed (leaves: 0.0).
`length` is the branch length printed in Newick:
    - non-root nodes: parent.height - node.height
    - root:           root.height - max(child heights)   (stem convention)
"""


def upgma(dist: dict[tuple[str, str], float], taxa: list[str]) -> dict:
    """Run UPGMA on a symmetric pairwise distance matrix given as a dict of
    unordered pairs -> distance."""
    clusters: dict[frozenset, dict] = {}
    for t in taxa:
        clusters[frozenset([t])] = {
            "name": t, "height": 0.0, "children": [], "size": 1,
        }

    # average distance between current clusters
    d: dict[tuple[frozenset, frozenset], float] = {}
    for i, a in enumerate(taxa):
        for b in taxa[i + 1:]:
            key = (frozenset([a]), frozenset([b]))
            d[key] = dist[tuple(sorted((a, b)))]

    while len(clusters) > 1:
        # closest pair of clusters (ties broken deterministically)
        (ci, cj), dij = min(d.items(), key=lambda kv: (kv[1], sorted(map(sorted, kv[0]))))
        ni, nj = clusters[ci]["size"], clusters[cj]["size"]
        height = dij / 2.0

        merged = {
            "name": None, "height": height, "size": ni + nj,
            "children": [
                _with_length(clusters[ci], height),
                _with_length(clusters[cj], height),
            ],
        }
        del clusters[ci], clusters[cj]

        # UPGMA average-distance update to every remaining cluster
        remaining = list(clusters)
        new_d = {}
        for ck in remaining:
            dk = (ni * d[(ci, ck)] if (ci, ck) in d else
                  ni * d[(ck, ci)] if (ck, ci) in d else None)
            if dk is None:
                raise KeyError("distance matrix incomplete")
            dk += nj * (d[(cj, ck)] if (cj, ck) in d else d[(ck, cj)])
            new_d[(frozenset(merged["name"] or []), ck)] = None  # placeholder key fix below
        # rebuild keys using the merged cluster id
        mid = frozenset(_members(merged))
        for ck in remaining:
            dik = d.get((ci, ck), d.get((ck, ci)))
            djk = d.get((cj, ck), d.get((ck, cj)))
            new_d[(mid, ck)] = (ni * dik + nj * djk) / (ni + nj)
        d = new_d
        clusters[mid] = merged

    (root,) = clusters.values()
    root["length"] = root["height"] - max(c["height"] for c in root["children"]) \
        if root["children"] else 0.0
    return root


def _members(node) -> set:
    if not node["children"]:
        return {node["name"]}
    out = set()
    for c in node["children"]:
        out |= _members(c)
    return out


def _with_length(node, parent_height: float) -> dict:
    node["length"] = parent_height - node["height"]
    return node


def canonical_newick(node) -> str:
    """Newick fragment; children sorted lexicographically by their own
    canonical serialization for a deterministic output."""
    if not node["children"]:
        s = node["name"]
    else:
        s = "(" + ",".join(sorted(canonical_newick(c) for c in node["children"])) + ")"
    return f"{s}:{node['length']:.1f}"


def newick(root) -> str:
    return canonical_newick(root) + ";"


def leaf_depths(node, depth=0.0) -> dict[str, float]:
    """Depth of each leaf = sum of branch lengths from (and including edges
    below) the root."""
    if not node["children"]:
        return {node["name"]: depth + node["length"]}
    out = {}
    for c in node["children"]:
        out.update(leaf_depths(c, depth + c["length"]))
    return out

