from upgma import upgma, newick, leaf_depths

DIST = {
    ("A", "B"): 2.0,
    ("A", "C"): 4.0, ("B", "C"): 4.0,
    ("A", "D"): 6.0, ("B", "D"): 6.0, ("C", "D"): 6.0,
}
TAXA = ["A", "B", "C", "D"]


def build():
    return upgma(DIST, TAXA)


def test_merge_order_and_heights():
    root = build()
    # root: D joins (A,B,C) at height 3
    assert abs(root["height"] - 3.0) < 1e-12
    abc, d = sorted(root["children"], key=lambda n: bool(n["children"]))
    assert not d["children"] and d["name"] == "D"
    assert abs(abc["height"] - 2.0) < 1e-12
    ab, c = sorted(abc["children"], key=lambda n: bool(n["children"]))
    assert not c["children"] and c["name"] == "C"
    assert abs(ab["height"] - 1.0) < 1e-12
    a, b = sorted((ch["name"] for ch in ab["children"]))
    assert [a, b] == ["A", "B"]


def test_canonical_newick():
    assert newick(build()) == "(((A:1.0,B:1.0):1.0,C:2.0):1.0,D:3.0);"


def test_ultrametric():
    depths = leaf_depths(build())
    assert set(depths) == {"A", "B", "C", "D"}
    for leaf, depth in depths.items():
        assert abs(depth - 3.0) < 1e-9, f"{leaf} depth {depth} != 3.0"


def test_input_order_independence():
    # shuffled taxa order must yield the same canonical tree
    for order in (["D", "C", "B", "A"], ["C", "A", "D", "B"], ["B", "D", "A", "C"]):
        assert newick(upgma(DIST, order)) == "(((A:1.0,B:1.0):1.0,C:2.0):1.0,D:3.0);"

